#!/usr/bin/env python3
"""For each handler name, locate its function definition and find plain spin_lock
acquisitions inside its body. Also find non-plain (irqsave/irq/bh) acquisitions inside.
Then cross-index: for each file, list lock expressions used plainly in the handler vs
plain spin_lock elsewhere in the same file (potential non-irq context)."""
import re, os
from collections import defaultdict

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C7/public/snapshots/s04"
T = os.environ.get("TMPDIR", "/tmp") + "/i047"

handlers = []
with open(T + "/handlers.txt") as f:
    for line in f:
        parts = line.rstrip("\n").split("\t")
        if len(parts) == 4:
            handlers.append((parts[0], int(parts[1]), parts[2], parts[3]))

def find_func_body(path, name):
    """Return (start_idx, body_lines) of the function definition in file, or None."""
    try:
        with open(os.path.join(ROOT, path), errors="replace") as f:
            lines = f.readlines()
    except OSError:
        return None
    # match definition: name(...) with opening brace at some line
    pat = re.compile(r"^[A-Za-z_].*?\b" + re.escape(name) + r"\s*\(")
    for i, l in enumerate(lines):
        if re.match(r"^(static\s+)?(inline\s+)?(irqreturn_t\s+|[a-zA-Z_][\w\s\*]*?)\b" + re.escape(name) + r"\s*\(", l):
            # find opening brace within next few lines
            j = i
            blob = ""
            while j < len(lines) and j < i + 12:
                blob += lines[j]
                # skip forward declarations ending with ';'
                if re.search(re.escape(name) + r"\s*\([^;]*\)\s*;", blob) and "{" not in blob:
                    break
                if "{" in blob:
                    # find matching close brace
                    depth = 0
                    started = False
                    k = i
                    body = []
                    while k < len(lines):
                        body.append(lines[k])
                        for ch in lines[k]:
                            if ch == "{":
                                depth += 1
                                started = True
                            elif ch == "}":
                                depth -= 1
                        if started and depth == 0:
                            return (i, body)
                        k += 1
                    return None
                j += 1
    return None

lock_re = re.compile(r"spin_lock(?:_irqsave|_irq|_bh)?\s*\(\s*(?:&\s*)?([^,\)\s]+)\s*")
# lock expression normalization: keep e.g. priv->lock or dev->lock[dev_id] simplified

results = []  # (path, regline, handler, kind, lockexpr, mode, body_line_no)
handler_cache = {}
for path, ln, h, kind in handlers:
    key = (path, h)
    if key not in handler_cache:
        handler_cache[key] = find_func_body(path, h)
    fb = handler_cache[key]
    if fb is None:
        continue
    start, body = fb
    for off, bl in enumerate(body):
        m = lock_re.search(bl)
        if m:
            lockexpr = m.group(1)
            mode = "plain" if "spin_lock(" in bl.replace("spin_lock_irqsave","SLIS").replace("spin_lock_irq","SLI").replace("spin_lock_bh","SLB") else None
            if m.group(0).startswith("spin_lock("):
                mode = "plain"
            elif m.group(0).startswith("spin_lock_irqsave"):
                mode = "irqsave"
            elif m.group(0).startswith("spin_lock_irq"):
                mode = "irq"
            elif m.group(0).startswith("spin_lock_bh"):
                mode = "bh"
            results.append((path, ln, h, kind, lockexpr, mode, start + off + 1))

print("handler lock acquisitions found:", len(results))
with open(T + "/handler_locks.tsv", "w") as f:
    for r in results:
        f.write("\t".join(str(x) for x in r) + "\n")

plain = [r for r in results if r[5] == "plain"]
print("plain handler lock acquisitions:", len(plain))
uniq = set((r[0], r[4]) for r in plain)
print("unique (file, lockexpr) with plain handler acquisition:", len(uniq))
PYEOF
python3 "$TMPDIR/i047/handler_locks.py"

cat > "$TMPDIR/i047/cross.py" << 'PYEOF'
#!/usr/bin/env python3
"""Cross-index: for each (file, lockexpr) with a plain handler acquisition, find
other plain spin_lock acquisitions of the same lock expression in the same file
OUTSIDE the handler body (potential non-irq context)."""
import re, os
from collections import defaultdict

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C7/public/snapshots/s04"
T = os.environ.get("TMPDIR", "/tmp") + "/i047"

lock_re = re.compile(r"spin_lock(?:_irqsave|_irq|_bh)?\s*\(\s*(?:&\s*)?([^,\)\s]+)\s*")

plain_pairs = defaultdict(set)   # (file, lockexpr) -> {regline}
handler_plain = defaultdict(list)  # (file, lockexpr) -> [(handler, regline, lockline)]

with open(T + "/handler_locks.tsv") as f:
    for line in f:
        parts = line.rstrip("\n").split("\t")
        if len(parts) != 7:
            continue
        path, regline, h, kind, lockexpr, mode, lockline = parts
        if mode == "plain":
            handler_plain[(path, lockexpr)].append((h, int(regline), int(lockline)))

out = []
for (path, lockexpr), hlist in handler_plain.items():
    try:
        with open(os.path.join(ROOT, path), errors="replace") as f:
            lines = f.readlines()
    except OSError:
        continue
    other_plain = []   # (lineno, line-content)
    other_safe = 0
    for i, l in enumerate(lines):
        m = lock_re.search(l)
        if not m:
            continue
        le = m.group(1)
        if le != lockexpr:
            continue
        # determine mode
        if m.group(0).startswith("spin_lock("):
            mode = "plain"
        elif m.group(0).startswith("spin_lock_irqsave"):
            mode = "irqsave"
        elif m.group(0).startswith("spin_lock_irq"):
            mode = "irq"
        elif m.group(0).startswith("spin_lock_bh"):
            mode = "bh"
        else:
            mode = "?"
        if mode != "plain":
            other_safe += 1
            continue
        # is this line inside one of the handler bodies?
        lineno = i + 1
        inhandler = False
        for (h, regline, lockline) in hlist:
            if abs(lineno - lockline) < 3:
                inhandler = True
        if not inhandler:
            other_plain.append((lineno, l.strip()))
    if other_plain:
        out.append((path, lockexpr, hlist, other_plain, other_safe))

out.sort(key=lambda x: -len(x[3]))
with open(T + "/cross.tsv", "w") as f:
    for path, lockexpr, hlist, other_plain, other_safe in out:
        f.write(f"{path}\t{lockexpr}\thandler_plain={len(hlist)}\tother_plain={len(other_plain)}\tother_safe={other_safe}\n")
        for (h, regline, lockline) in hlist[:3]:
            f.write(f"  HANDLER {h} reg={regline} lockline={lockline}\n")
        for (lineno, content) in other_plain[:6]:
            f.write(f"  OTHER {lineno}: {content}\n")
print("candidate (file, lock) pairs with plain handler AND plain elsewhere:", len(out))
print()
with open(T + "/cross.tsv") as f:
    print(f.read()[:6000])
PYEOF
python3 "$TMPDIR/i047/cross.py"

